; calls.asm -- appendix F: every BIOS entry point of bios.inc, called once
; generated by genF.py
        INCLUDE "msx.inc"
        INCLUDE "bios.inc"
        OUTPUT "calls.rom"
        ORG $4000
        CART_HEADER init
; Before each call every register gets a value of its own (markers, at the
; end), then the call's inputs.
init:   di
        ld sp, SYS_AREA
; RDSLT: the byte at $002B of slot 0
rdslt:  ei
        halt                    ; just after a frame's interrupt
        di
        call markers            ; every register a value of its own
        ld a, $00
        ld hl, $002B
b_rdslt: call RDSLT
a_rdslt: nop
; WRSLT: $5A to $E000 of slot 3, the RAM
wrslt:  ei
        halt                    ; just after a frame's interrupt
        di
        call markers            ; every register a value of its own
        ld a, $03
        ld hl, $E000
        ld e, $5A
b_wrslt: call WRSLT
a_wrslt: nop
; CALSLT: RSLREG, in slot 0
calslt: ei
        halt                    ; just after a frame's interrupt
        di
        call markers            ; every register a value of its own
        ld iy, $0000
        ld ix, RSLREG
b_calslt: call CALSLT
a_calslt: nop
; ENASLT: page 1 to slot 1, where it is
enaslt: ei
        halt                    ; just after a frame's interrupt
        di
        call markers            ; every register a value of its own
        ld a, $01
        ld h, $40
b_enaslt: call ENASLT
a_enaslt: nop
; DISSCR: the display off
disscr: ei
        halt                    ; just after a frame's interrupt
        di
        call markers            ; every register a value of its own
b_disscr: call DISSCR
a_disscr: nop
; ENASCR: the display on
enascr: ei
        halt                    ; just after a frame's interrupt
        di
        call markers            ; every register a value of its own
b_enascr: call ENASCR
a_enascr: nop
; WRTVDP: $F4 to R#7
wrtvdp: ei
        halt                    ; just after a frame's interrupt
        di
        call markers            ; every register a value of its own
        ld b, $F4
        ld c, 7
b_wrtvdp: call WRTVDP
a_wrtvdp: nop
; RDVRM: the byte at $1800
rdvrm:  ei
        halt                    ; just after a frame's interrupt
        di
        call markers            ; every register a value of its own
        ld hl, $1800
b_rdvrm: call RDVRM
a_rdvrm: nop
; WRTVRM: $41 to $1800
wrtvrm: ei
        halt                    ; just after a frame's interrupt
        di
        call markers            ; every register a value of its own
        ld hl, $1800
        ld a, $41
b_wrtvrm: call WRTVRM
a_wrtvrm: nop
; SETRD: a read address, $1800
setrd:  ei
        halt                    ; just after a frame's interrupt
        di
        call markers            ; every register a value of its own
        ld hl, $1800
b_setrd: call SETRD
a_setrd: nop
; SETWRT: a write address, $1800
setwrt: ei
        halt                    ; just after a frame's interrupt
        di
        call markers            ; every register a value of its own
        ld hl, $1800
b_setwrt: call SETWRT
a_setwrt: nop
; FILVRM: 28 bytes of $20 from $1800, as chapter 19 filled
filvrm: ei
        halt                    ; just after a frame's interrupt
        di
        call markers            ; every register a value of its own
        ld hl, $1800
        ld bc, 28
        ld a, $20
b_filvrm: call FILVRM
a_filvrm: nop
; LDIRVM: 16 bytes from the ROM to $1800
ldirvm: ei
        halt                    ; just after a frame's interrupt
        di
        call markers            ; every register a value of its own
        ld hl, text
        ld de, $1800
        ld bc, 16
b_ldirvm: call LDIRVM
a_ldirvm: nop
; CHGMOD: screen mode 1, Graphic I
chgmod: ei
        halt                    ; just after a frame's interrupt
        di
        call markers            ; every register a value of its own
        ld a, 1
b_chgmod: call CHGMOD
a_chgmod: nop
; INIMLT: multicolour
inimlt: ei
        halt                    ; just after a frame's interrupt
        di
        call markers            ; every register a value of its own
b_inimlt: call INIMLT
a_inimlt: nop
; INIGRP: Graphic II
inigrp: ei
        halt                    ; just after a frame's interrupt
        di
        call markers            ; every register a value of its own
b_inigrp: call INIGRP
a_inigrp: nop
; INIT32: Graphic I
init32: ei
        halt                    ; just after a frame's interrupt
        di
        call markers            ; every register a value of its own
b_init32: call INIT32
a_init32: nop
; INITXT: text mode
initxt: ei
        halt                    ; just after a frame's interrupt
        di
        call markers            ; every register a value of its own
b_initxt: call INITXT
a_initxt: nop
; CHPUT: the letter A
chput:  ei
        halt                    ; just after a frame's interrupt
        di
        call markers            ; every register a value of its own
        ld a, $41
b_chput: call CHPUT
a_chput: nop
; CHSNS: no key waiting
chsns:  ei
        halt                    ; just after a frame's interrupt
        di
        call markers            ; every register a value of its own
b_chsns: call CHSNS
a_chsns: nop
; BEEP: a beep
beep:   ei
        halt                    ; just after a frame's interrupt
        di
        call markers            ; every register a value of its own
b_beep: call BEEP
a_beep: nop
; GTSTCK: the cursor keys, none held
gtstck: ei
        halt                    ; just after a frame's interrupt
        di
        call markers            ; every register a value of its own
        ld a, 0
b_gtstck: call GTSTCK
a_gtstck: nop
; GTTRIG: SPACE, not held
gttrig: ei
        halt                    ; just after a frame's interrupt
        di
        call markers            ; every register a value of its own
        ld a, 0
b_gttrig: call GTTRIG
a_gttrig: nop
; RSLREG: port $A8
rslreg: ei
        halt                    ; just after a frame's interrupt
        di
        call markers            ; every register a value of its own
b_rslreg: call RSLREG
a_rslreg: nop
; WSLREG: port $A8 written as it is
wslreg: ei
        halt                    ; just after a frame's interrupt
        di
        call markers            ; every register a value of its own
        in a, (PPI_A)
b_wslreg: call WSLREG
a_wslreg: nop
; SNSMAT: row 8, nothing held
snsmat: ei
        halt                    ; just after a frame's interrupt
        di
        call markers            ; every register a value of its own
        ld a, 8
b_snsmat: call SNSMAT
a_snsmat: nop
; RDSLT: the byte at $002B of slot 0, the interrupts on
rdslt_e: ei
        halt                    ; just after a frame's interrupt
        di
        call markers            ; every register a value of its own
        ld a, $00
        ld hl, $002B
        ei
b_rdslt_e: call RDSLT
a_rdslt_e: nop
; WRSLT: $5A to $E000 of slot 3, the RAM, the interrupts on
wrslt_e: ei
        halt                    ; just after a frame's interrupt
        di
        call markers            ; every register a value of its own
        ld a, $03
        ld hl, $E000
        ld e, $5A
        ei
b_wrslt_e: call WRSLT
a_wrslt_e: nop
; CALSLT: RSLREG, in slot 0, the interrupts on
calslt_e: ei
        halt                    ; just after a frame's interrupt
        di
        call markers            ; every register a value of its own
        ld iy, $0000
        ld ix, RSLREG
        ei
b_calslt_e: call CALSLT
a_calslt_e: nop
; ENASLT: page 1 to slot 1, where it is, the interrupts on
enaslt_e: ei
        halt                    ; just after a frame's interrupt
        di
        call markers            ; every register a value of its own
        ld a, $01
        ld h, $40
        ei
b_enaslt_e: call ENASLT
a_enaslt_e: nop
; BEEP: a beep, the interrupts on
beep_e: ei
        halt                    ; just after a frame's interrupt
        di
        call markers            ; every register a value of its own
        ei
b_beep_e: call BEEP
a_beep_e: nop
; RSLREG: port $A8, the interrupts on
rslreg_e: ei
        halt                    ; just after a frame's interrupt
        di
        call markers            ; every register a value of its own
        ei
b_rslreg_e: call RSLREG
a_rslreg_e: nop
; WSLREG: port $A8 written as it is, the interrupts on
wslreg_e: ei
        halt                    ; just after a frame's interrupt
        di
        call markers            ; every register a value of its own
        in a, (PPI_A)
        ei
b_wslreg_e: call WSLREG
a_wslreg_e: nop

; the keys: wait, frame by frame, until row 8 of the keyboard shows SPACE
; held, read on the PPI's own ports, then 10 frames for the BIOS to read them
keys:   ei
        halt
        di
        in a, (PPI_C)
        and $F0
        or 8
        out (PPI_C), a          ; row 8
        in a, (PPI_B)
        bit 0, a                ; SPACE: 0 while held
        jr nz, keys
        ld b, 10
settle: ei
        halt
        djnz settle
; GTSTCK: the cursor keys, RIGHT held
gtstck_k: ei
        halt                    ; just after a frame's interrupt
        di
        call markers            ; every register a value of its own
        ld a, 0
b_gtstck_k: call GTSTCK
a_gtstck_k: nop
; GTTRIG: SPACE, held
gttrig_k: ei
        halt                    ; just after a frame's interrupt
        di
        call markers            ; every register a value of its own
        ld a, 0
b_gttrig_k: call GTTRIG
a_gttrig_k: nop
; SNSMAT: row 8, SPACE and RIGHT held
snsmat_k: ei
        halt                    ; just after a frame's interrupt
        di
        call markers            ; every register a value of its own
        ld a, 8
b_snsmat_k: call SNSMAT
a_snsmat_k: nop
; CHSNS: a key waiting
chsns_k: ei
        halt                    ; just after a frame's interrupt
        di
        call markers            ; every register a value of its own
b_chsns_k: call CHSNS
a_chsns_k: nop
; CHGET: the key waiting
chget_k: ei
        halt                    ; just after a frame's interrupt
        di
        call markers            ; every register a value of its own
b_chget_k: call CHGET
a_chget_k: nop

done:   di
        jr done

; every register a value of its own: AF $A5C3, BC $B1C1, DE $D1E1, HL $4171,
; IX $1F2F, IY $3F4F, AF' $5AC5, BC' $B2C2, DE' $D2E2, HL' $4272
markers: ld hl, $5AC5
        push hl
        pop af
        ex af, af'
        exx
        ld bc, $B2C2
        ld de, $D2E2
        ld hl, $4272
        exx
        ld hl, $A5C3
        push hl
        pop af
        ld bc, $B1C1
        ld de, $D1E1
        ld hl, $4171
        ld ix, $1F2F
        ld iy, $3F4F
        ret

text:   db "THE BIOS, CALLED"   ; LDIRVM's sixteen bytes
        ASSERT $ - text == 16
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
